from fractions import Fraction
import math

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def angle_steps(label, u, v):
    print(f"{label}: {show(u)} and {show(v)}")
    d, uu, vv = dot(u, v), dot(u, u), dot(v, v)
    print(f"  u·v = {d}, ‖u‖² = {uu}, ‖v‖² = {vv}")
    if uu == 0 or vv == 0:
        print("  undefined: a zero vector has no direction")
        return
    n = uu * vv
    if math.isqrt(n) ** 2 == n:
        exact = str(Fraction(d, math.isqrt(n)))
    else:
        exact = f"{d}/sqrt({n})"
    if d == 0:
        exact = "0"
    c = d / math.sqrt(n)
    if d * d == n and d > 0:
        kind = "same direction"
    elif d * d == n:
        kind = "opposite directions"
    elif d > 0:
        kind = "acute"
    elif d < 0:
        kind = "obtuse"
    else:
        kind = "right angle, orthogonal"
    if exact in ("0", "1", "-1"):
        print(f"  cos θ = {exact}")
    else:
        print(f"  cos θ = {exact} = {c:.6f}")
    print(f"  θ = {math.degrees(math.acos(c)):.2f} degrees, {kind}")

angle_steps("Case 1 · the plain case", [1, 0], [1, 1])
angle_steps("Case 2 · three dimensions", [1, 2, 2], [2, 0, 1])
angle_steps("Case 3 · orthogonal", [3, -1, 2], [1, 5, 1])
angle_steps("Case 4 · parallel", [2, 4], [1, 2])
angle_steps("Case 5 · opposite", [2, 4], [-1, -2])
angle_steps("Case 6 · the zero vector", [0, 0], [3, 4])
angle_steps("Case 7 · the hikers", [3, 4], [5, 12])

